import test from 'node:test';import assert from 'node:assert/strict';
import {defaultMachines,normalizeMachines,machineBlueprints,machineParts,machineSlots,machineCommand,machineReady,machineView,machineSvg,machineMotion,machinePartArtKeys,machinePartSvg,machineSites,machinePadAllows,machineObjects} from '../src/machines.js';import {objects,materials} from '../src/data.js';import {pathfind,cellAt} from '../src/navigation.js';import {zones} from '../src/zones.js';import {getJournalEntries} from '../src/journal.js';
const context={earthReady:true,moonReady:true};
function build(s=defaultMachines(),type='rover'){s=machineCommand(s,{type:'blueprint',value:type},context).machines;for(const slot of machineSlots(type))s=machineCommand(s,{type:'part',slot,value:machineBlueprints[type].slots[slot][0]},context).machines;return s;}
function save(s,type){s=build(s,type);return machineCommand(s,{type:'save'},context).machines;}
test('eleven blueprints share a small vocabulary; passive structures omit engines/computers and rockets use matched propellant',()=>{assert.equal(Object.keys(machineBlueprints).length,11);for(const type of ['bridge','tower'])assert.deepEqual(machineSlots(type),['frame','fasteners','module']);for(const type of ['rover','crane','rocket','submarine','airplane'])assert.equal(machineSlots(type).length,6);assert.deepEqual(machineBlueprints.rocket.slots.power,['tank','twintank']);assert.equal(machineBlueprints.rocket.slots.motion.includes('wheels'),false);assert.equal(machineBlueprints.submarine.slots.power.includes('tank'),false);assert.deepEqual(machineBlueprints.rover.slots.computer,['computer']);assert.match(machineParts.wheels.text,/motor and gears/);});
test('every offered component fits, changes the visible design and can be saved and tested',()=>{for(const type of Object.keys(machineBlueprints)){const s=build(defaultMachines(),type),d=s.drafts[type];assert.ok(machineReady(d));assert.notEqual(machineSvg({...d,color:'orange'}),machineSvg(d),type);for(const slot of machineSlots(type))for(const value of machineBlueprints[type].slots[slot]){const altered=machineCommand(s,{type:'part',slot,value}).machines;assert.ok(machineReady(altered.drafts[type]));assert.match(machineSvg(altered.drafts[type]),/viewBox="0 0 360 200"/);if(value!==d.parts[slot])assert.notEqual(machineSvg(altered.drafts[type]),machineSvg(d));assert.equal(machineCommand(altered,{type:'test'}).route,'test');}assert.equal(machineCommand(s,{type:'save'}).machines.models.length,1);}});
test('incomplete drafts cannot save; PIP fills missing slots without replacing custom choices, undo restores paint/parts',()=>{let s=machineCommand(defaultMachines(),{type:'blueprint',value:'rover'}).machines;assert.equal(machineCommand(s,{type:'save'}).machines.models.length,0);s=machineCommand(s,{type:'part',slot:'motion',value:'legs'}).machines;s=machineCommand(s,{type:'helper'}).machines;assert.equal(s.drafts.rover.parts.motion,'legs');assert.ok(machineReady(s.drafts.rover));s=machineCommand(s,{type:'color',value:'orange'}).machines;assert.equal(s.drafts.rover.color,'orange');s=machineCommand(s,{type:'undo'}).machines;assert.equal(s.drafts.rover.color,'blue');assert.equal(machineCommand(s,{type:'part',slot:'motion',value:'nozzle'}).machines.drafts.rover.parts.motion,'legs');});
test('saving, edit/copy and deployment use separate snapshots; editing one model never changes an existing placement',()=>{let s=save(defaultMachines(),'rover');s=machineCommand(s,{type:'deploy',id:'m1',site:'machineyard',pad:0},context).machines;const placed=structuredClone(s.placements[0].snapshot);s=machineCommand(s,{type:'edit',id:'m1'}).machines;s=machineCommand(s,{type:'part',slot:'motion',value:'tracks'}).machines;s=machineCommand(s,{type:'save'}).machines;assert.equal(s.models.length,1);assert.equal(s.models[0].parts.motion,'tracks');assert.deepEqual(s.placements[0].snapshot,placed);s=machineCommand(s,{type:'copy',id:'m1'}).machines;s=machineCommand(s,{type:'save'}).machines;assert.equal(s.models.length,2);assert.equal(s.models[1].parts.motion,'tracks');assert.deepEqual(normalizeMachines(JSON.parse(JSON.stringify(s))),s);});
test('repair checks retain chosen parts and never gate a working machine or charge resources',()=>{let s=save(defaultMachines(),'rocket'),parts=structuredClone(s.models[0].parts);s=machineCommand(s,{type:'service',id:'m1'}).machines;for(const value of ['structure','drive','control','control'])s=machineCommand(s,{type:'check',id:'m1',value}).machines;assert.deepEqual(s.service.m1,['structure','drive','control']);assert.deepEqual(s.models[0].parts,parts);assert.deepEqual(s.serviced,['m1']);assert.equal(machineCommand(s,{type:'deploy',id:'m1',site:'machineyard',pad:1},context).machines.placements.length,1);});
test('placements respect water/atmosphere, world access and surface connections; replacement keeps saved designs',()=>{let s=save(defaultMachines(),'airplane');assert.equal(machineCommand(s,{type:'deploy',id:'m1',site:'chapterMoon',pad:1},context).machines.placements.length,0);s=save(s,'rocket');assert.equal(machineCommand(s,{type:'deploy',id:'m2',site:'chapterMoon',pad:1},{}).machines.placements.length,0);assert.equal(machinePadAllows('rocket','chapterMoon',0),false);s=machineCommand(s,{type:'deploy',id:'m2',site:'chapterMoon',pad:1},context).machines;assert.equal(s.placements.length,1);s=machineCommand(s,{type:'deploy',id:'m1',site:'machineyard',pad:0},context).machines;s=machineCommand(s,{type:'deploy',id:'m2',site:'machineyard',pad:0},context).machines;assert.equal(s.placements.length,2);assert.equal(s.models.length,2);assert.equal(s.placements.find(p=>p.site==='machineyard').modelId,'m2');assert.equal(machineView(s,'sites:m1',context).actions.some(a=>a.label.includes('Moon')),false);});
test('old/corrupt saves recover compatible saved models and reject unknown IDs, locations and out-of-range pads',()=>{const s=normalizeMachines({active:'bad',models:[{id:'m1',type:'rocket',parts:{motion:'wheels',power:'battery'},color:'bad'},{id:'m1',type:'rover'},{id:'m2',type:'unknown'}],placements:[{site:'bad',pad:0,modelId:'m1'},{site:'machineyard',pad:99,modelId:'m1'}]});assert.equal(s.models.length,1);assert.ok(machineReady(s.models[0]));assert.equal(s.models[0].parts.motion,'nozzle');assert.equal(s.models[0].color,'blue');assert.equal(s.placements.length,0);assert.deepEqual(normalizeMachines(null),defaultMachines());});
test('every builder/library/service/placement page fits native choices and demo poses support static reduced effects',()=>{let s=defaultMachines();for(const type of Object.keys(machineBlueprints))s=save(s,type);for(const m of s.models){s=machineCommand(s,{type:'edit',id:m.id}).machines;const pages=['home','group:vehicles','group:structures','group:helpers','build:0','build:1','controls','paint','test','library:0','library:1','library:2','model:'+m.id,'service:'+m.id,'sites:'+m.id,'yard','deployments:0',...machineSlots(m.type).map(k=>'slot:'+k)];for(const [site,config]of Object.entries(machineSites))if(config.types.includes(m.type)){pages.push('pads:'+m.id+':'+site);for(let pad=0;pad<config.pads.length;pad++)pages.push('place:'+m.id+':'+site+':'+pad);}for(const route of pages){const v=machineView(s,route,context);assert.ok(v.actions.length<=5,route);assert.ok(v.title&&v.text);assert.ok(v.text.replace(/(.{1,43})(?:\s|$)/g,'$1\n').trim().split('\n').length<=7,v.text);}}assert.notDeepEqual(machineMotion('rover',0),machineMotion('rover',1));assert.deepEqual(machineMotion('rover',0,true),machineMotion('rover',99,true));for(const key of machinePartArtKeys)assert.match(machinePartSvg(key),/viewBox="0 0 100 100"/);});
test('engineering entry, sandbox controls and saved journal entries are reachable without replacing previous construction',()=>{for(const o of machineObjects.filter(o=>o.zone==='engineering'||o.zone==='machineyard'))assert.ok(pathfind(zones[o.zone].spawn,[o.x-65,o.y+55],o.zone).length||cellAt(...zones[o.zone].spawn,o.zone).join()===cellAt(o.x-65,o.y+55,o.zone).join(),o.id);const s=save(defaultMachines(),'submarine'),entries=getJournalEntries('did',new Set(),new Set(),objects,materials,{}, {},{}, {},{},s);assert.equal(entries.length,1);assert.equal(entries[0].machineId,'m1');assert.equal(entries[0].target,'yard-my-machines');assert.equal(new Set(objects.map(o=>o.id)).size,objects.length);});

test('deployed farm rovers and solar stations expose distinct useful effects without consuming their saved parts',()=>{let s=save(defaultMachines(),'rover');s=machineCommand(s,{type:'deploy',id:'m1',site:'farm',pad:0},context).machines;assert.equal(machineCommand(s,{type:'use',site:'farm',pad:0}).effect,'water-bed');s=save(s,'solar');s=machineCommand(s,{type:'deploy',id:'m2',site:'farm',pad:0},context).machines;assert.equal(machineCommand(s,{type:'use',site:'farm',pad:0}).effect,'farm-light');assert.equal(s.models.length,2);assert.equal(s.placements.length,1);assert.ok(s.models.every(machineReady));});
